import { AssumeRoleCommand, STSClient } from '@aws-sdk/client-sts';
import type { AwsCredentialIdentity } from '@aws-sdk/types';

export const DEFAULT_ROLE_SESSION_NAME = 'meteringco-role-validation';

export const defaultRegion = (): string => process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

/**
 * Assumes the given role, optionally with an external id, and hands back the temporary credentials
 * returned by STS. Throws whatever error STS returns, callers are expected to handle it.
 */
export const assumeRoleWithExternalId = async ({
    roleArn,
    externalId,
    region = defaultRegion(),
    roleSessionName = DEFAULT_ROLE_SESSION_NAME,
}: {
    roleArn: string;
    externalId?: string;
    region?: string;
    roleSessionName?: string;
}): Promise<AwsCredentialIdentity> => {
    const client = new STSClient({ region });
    const { Credentials } = await client.send(
        new AssumeRoleCommand({
            RoleArn: roleArn,
            RoleSessionName: roleSessionName,
            ExternalId: externalId ? externalId : undefined,
        }),
    );
    if (!Credentials?.AccessKeyId || !Credentials?.SecretAccessKey) {
        throw new Error(`STS did not return any credentials for role ${roleArn}`);
    }
    return {
        accessKeyId: Credentials.AccessKeyId,
        secretAccessKey: Credentials.SecretAccessKey,
        sessionToken: Credentials.SessionToken,
        expiration: Credentials.Expiration,
    };
};
