import { Test, TestingModule } from '@nestjs/testing';
import { BadRequestException } from '@nestjs/common';
import { createMock } from '@golevelup/ts-jest';
import { CreateRoleCommand, IAMClient, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { GetCallerIdentityCommand, STSClient } from '@aws-sdk/client-sts';
import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { SettingsService } from './settings.service.js';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';
import { InfluxService } from '../influx/influx.service.js';

const businessID = 'some-business-id';
const subject = 'some-subject';
const EXTERNAL_ID = 'meteringco-scraper-external-id';

const readOnlyEc2Policy = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }],
};
const noEc2Policy = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Action: ['s3:ListBucket'], Resource: '*' }],
};

const trustPolicy = (accountId: string, externalId?: string) =>
    JSON.stringify({
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: `arn:aws:iam::${accountId}:root` },
                Action: 'sts:AssumeRole',
                ...(externalId ? { Condition: { StringEquals: { 'sts:ExternalId': externalId } } } : {}),
            },
        ],
    });

const iam = new IAMClient({});

const ensureRole = async (roleName: string, accountId: string, externalId: string, policy: unknown) => {
    try {
        await iam.send(
            new CreateRoleCommand({ RoleName: roleName, AssumeRolePolicyDocument: trustPolicy(accountId, externalId) }),
        );
    } catch (e) {
        // The role already exists from a previous run, that is fine.
    }
    await iam.send(
        new PutRolePolicyCommand({
            RoleName: roleName,
            PolicyName: 'scraper',
            PolicyDocument: JSON.stringify(policy),
        }),
    );
    return `arn:aws:iam::${accountId}:role/${roleName}`;
};

describe('cloudIAM scraper role', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    let assumableRole: string;
    let roleWithoutInventoryAccess: string;
    let roleWithoutExternalId: string;

    beforeAll(async () => {
        const { Account } = await new STSClient({}).send(new GetCallerIdentityCommand({}));
        assumableRole = await ensureRole('meteringco-spec-scraper', Account, EXTERNAL_ID, readOnlyEc2Policy);
        roleWithoutInventoryAccess = await ensureRole(
            'meteringco-spec-scraper-no-inventory',
            Account,
            EXTERNAL_ID,
            noEc2Policy,
        );
        roleWithoutExternalId = await ensureRole(
            'meteringco-spec-scraper-no-external-id',
            Account,
            undefined,
            readOnlyEc2Policy,
        );
    });

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
    });

    afterEach(() => jest.clearAllMocks());

    describe('saving settings', () => {
        it('saves a role that can be assumed with the external id and can read the instance inventory', async () => {
            const { data } = await service.update({
                businessID,
                subject,
                cloudIAM: { iamRoleArn: assumableRole, externalId: EXTERNAL_ID },
            });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].cloudIAM).toEqual({ iamRoleArn: assumableRole, externalId: EXTERNAL_ID });
        });

        it('saves a role that does not require an external id', async () => {
            const { data } = await service.update({
                businessID,
                subject,
                cloudIAM: { iamRoleArn: roleWithoutExternalId },
            });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].cloudIAM).toEqual({ iamRoleArn: roleWithoutExternalId });
        });

        it('rejects a role that cannot be assumed with the external id supplied', async () => {
            let error;
            try {
                await service.update({
                    businessID,
                    subject,
                    vatId: '123456',
                    cloudIAM: { iamRoleArn: assumableRole, externalId: 'not the external id' },
                });
            } catch (e) {
                error = e;
            }
            expect(error).toBeInstanceOf(BadRequestException);
            expect(error.getStatus()).toBe(400);
            expect(error.getResponse().message[0]).toEqual(expect.stringContaining('IAM'));
            // Nothing else in the save may be written
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('rejects a role that requires an external id when none is supplied', async () => {
            await expect(
                service.update({ businessID, subject, cloudIAM: { iamRoleArn: assumableRole } }),
            ).rejects.toThrow(BadRequestException);
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('rejects a role that does not exist', async () => {
            await expect(
                service.update({ businessID, subject, cloudIAM: { iamRoleArn: 'wow a fake role', externalId: 'x' } }),
            ).rejects.toThrow(/IAM/);
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('rejects a role that can be assumed but cannot read the instance inventory', async () => {
            let error;
            try {
                await service.update({
                    businessID,
                    subject,
                    cloudIAM: { iamRoleArn: roleWithoutInventoryAccess, externalId: EXTERNAL_ID },
                });
            } catch (e) {
                error = e;
            }
            expect(error).toBeInstanceOf(BadRequestException);
            expect(error.getResponse().message[0]).toEqual(expect.stringContaining('IAM'));
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('treats a cloudIAM block that names no role as a bad request instead of a disconnect', async () => {
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore no role given on purpose
            await expect(service.update({ businessID, subject, cloudIAM: {} })).rejects.toThrow(BadRequestException);
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore no role given on purpose
            await expect(service.update({ businessID, subject, cloudIAM: { externalId: EXTERNAL_ID } })).rejects.toThrow(
                BadRequestException,
            );
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('treats a blank role as a disconnect and clears the external id', async () => {
            const { data } = await service.update({
                businessID,
                subject,
                cloudIAM: { iamRoleArn: '', externalId: EXTERNAL_ID },
            });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].cloudIAM).toEqual({ iamRoleArn: '', externalId: '' });
        });

        it('does not touch the cloud IAM configuration when the save does not carry one', async () => {
            const { data } = await service.update({ businessID, subject, vatId: '123' });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].vatId).toEqual('123');
        });
    });

    describe('request validation', () => {
        const validateCloudIAM = async (cloudIAM) =>
            JSON.stringify(await validate(plainToInstance(UpdateSettingsDto, { cloudIAM }), { whitelist: true }));

        it('accepts a provable role', async () => {
            expect(await validateCloudIAM({ iamRoleArn: assumableRole, externalId: EXTERNAL_ID })).toEqual('[]');
        });

        it('accepts a blank role', async () => {
            expect(await validateCloudIAM({ iamRoleArn: '' })).toEqual('[]');
        });

        it('rejects a role that cannot be assumed with the external id supplied', async () => {
            const errors = await validateCloudIAM({ iamRoleArn: assumableRole, externalId: 'nope' });
            expect(errors).not.toEqual('[]');
            expect(errors).toEqual(expect.stringContaining('IAM'));
        });

        it('rejects a role that cannot read the instance inventory', async () => {
            const errors = await validateCloudIAM({ iamRoleArn: roleWithoutInventoryAccess, externalId: EXTERNAL_ID });
            expect(errors).toEqual(expect.stringContaining('inventory'));
        });

        it('rejects a cloudIAM block that names no role', async () => {
            expect(await validateCloudIAM({})).not.toEqual('[]');
        });
    });
});
