  "output": "import { BadRequestException, Injectable, Logger } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { assumeRoleWithExternalId, defaultRegion } from '../../utils/aws/sts.js';
import { describeInstanceInventory } from '../../utils/aws/awsEc2.js';

const logger = new Logger('CloudIAMAuthorizer');

/**
 * A settings payload that carries a cloudIAM block, but does not name a role, is a bad request.
 * Disconnecting is done by explicitly sending an empty role.
 */
export const CLOUD_IAM_MISSING_ROLE_MESSAGE =
    'cloudIAM.iamRoleArn must be provided, send an IAM role arn to connect an AWS account or an empty string to disconnect';

export const CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE =
    'Unable to assume the IAM role provided with the external ID provided. Please double check the IAM role arn, its trust policy and the external ID';

export const CLOUD_IAM_INVENTORY_FAILURE_MESSAGE =
    'The IAM role provided was assumed but it is not able to read the EC2 instance inventory used for collection (ec2:DescribeInstances). Please double check the permissions attached to the IAM role';

export interface CloudIAMLike {
    iamRoleArn?: string;
    externalId?: string;
}

export interface SavedCloudIAM {
    iamRoleArn: string;
    externalId?: string;
}

/**
 * An empty (or whitespace only) role arn is how a customer disconnects their AWS account.
 */
export const isCloudIAMDisconnect = (cloudIAM: CloudIAMLike): boolean =>
    typeof cloudIAM?.iamRoleArn === 'string' && cloudIAM.iamRoleArn.trim() === '';

const namesARole = (cloudIAM: unknown): cloudIAM is CloudIAMLike =>
    !!cloudIAM &&
    typeof cloudIAM === 'object' &&
    !Array.isArray(cloudIAM) &&
    typeof (cloudIAM as CloudIAMLike).iamRoleArn === 'string';

/**
 * Proves that the supplied role can be assumed with the supplied external id and that the
 * credentials handed back are able to read the instance inventory collection depends on.
 *
 * Returns null when the cloudIAM block is acceptable, otherwise the reason it is not.
 */
export const findCloudIAMProblem = async (cloudIAM: unknown, region: string = defaultRegion()): Promise<string> => {
    if (!namesARole(cloudIAM)) {
        return CLOUD_IAM_MISSING_ROLE_MESSAGE;
    }
    if (isCloudIAMDisconnect(cloudIAM)) {
        // Disconnecting, there is nothing to prove.
        return null;
    }
    const iamRoleArn = cloudIAM.iamRoleArn.trim();
    const { externalId } = cloudIAM;
    let credentials;
    try {
        credentials = await assumeRoleWithExternalId({ roleArn: iamRoleArn, externalId, region });
    } catch (e) {
        logger.error(`Failed to assume customer role ${iamRoleArn}: ${e?.name} ${e?.message}`);
        return CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE;
    }
    try {
        await describeInstanceInventory(region, credentials);
    } catch (e) {
        logger.error(
            `Assumed customer role ${iamRoleArn} but could not read the instance inventory: ${e?.name} ${e?.message}`,
        );
        return CLOUD_IAM_INVENTORY_FAILURE_MESSAGE;
    }
    return null;
};

/**
 * Shapes what actually gets persisted. Disconnecting clears the external id so a stale external id
 * is never left behind on the account.
 */
export const normalizeCloudIAM = (cloudIAM: CloudIAMLike): SavedCloudIAM => {
    if (isCloudIAMDisconnect(cloudIAM)) {
        return { iamRoleArn: '', externalId: '' };
    }
    const iamRoleArn = cloudIAM.iamRoleArn.trim();
    return typeof cloudIAM.externalId === 'string' ? { iamRoleArn, externalId: cloudIAM.externalId } : { iamRoleArn };
};

const badRequest = (message: string): BadRequestException => {
    // Keep the body shape consistent with the validation pipe (message as an array of problems)
    // while still carrying a useful `error.message` for internal callers.
    const exception = new BadRequestException({ statusCode: 400, message: [message], error: 'Bad Request' });
    exception.message = message;
    return exception;
};

/**
 * Validates the cloudIAM block of a settings update and returns what should be saved.
 * Throws a BadRequestException, before anything is written, if either check fails.
 */
export const validateCloudIAMForSave = async (
    cloudIAM: CloudIAMLike,
    region: string = defaultRegion(),
): Promise<SavedCloudIAM> => {
    const problem = await findCloudIAMProblem(cloudIAM, region);
    if (problem) {
        throw badRequest(problem);
    }
    return normalizeCloudIAM(cloudIAM);
};

@ValidatorConstraint({ name: 'ValidCloudIAMRoleRule', async: true })
@Injectable()
export class ValidCloudIAMRoleRule implements ValidatorConstraintInterface {
    private problem: string = CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE;

    async validate(iamRoleArn: string, args: ValidationArguments): Promise<boolean> {
        const cloudIAM = (args?.object ?? {}) as CloudIAMLike;
        const problem = await findCloudIAMProblem({ ...cloudIAM, iamRoleArn });
        if (problem) {
            this.problem = problem;
            return false;
        }
        return true;
    }

    defaultMessage(): string {
        return this.problem;
    }
}

export function ValidCloudIAMRole(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidCloudIAMRole',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [],
            options: validationOptions,
            validator: ValidCloudIAMRoleRule,
        });
    };
}
